function mostrarHeaderFooter() {
	var requestHeader = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/mostrar_header_2.php",
		method: "GET",
		dataType: "html"
	});

	var requestFooter = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/mostrar_footer_2.php",
		method: "GET",
		dataType: "html"
	});

	requestHeader.done(function(pagina) {
		$("header").html(pagina);
		$('.closebtn').css('display', 'none');
		if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent))
			$('.navbar-nav > li').addClass('mobile');
		else
			$('.navbar-nav > li').addClass('computer')

		$('.prisma-header').on('focus', '.form-control', function() {
			$(this).next().next().addClass('active');
		});
		$('.prisma-header').on('blur', '.form-control', function() {
			if ($(this).val() == '')
				$(this).next().next().removeClass('active');
		});
	});

	requestHeader.fail(function(jqXHR, textStatus, errorThrown) {
		errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request Header: ");
	});

	requestFooter.done(function(pagina) {
		$("footer").html(pagina);

		adjustStyle();

		$(window).resize(function() {
			adjustStyle();
		});

		$('.form-footer').on('focus', '.form-control', function() {
			$('.form-footer label').hide();
		});
		$('.form-footer').on('blur', '.form-control', function() {
			if ($('#adreca-electronica').val() == '')
				$('.form-footer label').show();
		});

		function mostrarErrorButlleti(missatgeError) {
			$('#modalErrorBody').html(missatgeError);
			$('#modalError').modal('show')
		}

		function mostrarSuccessButlleti(missatgeSuccess) {
			$('#modalOkBody').html(missatgeSuccess);
			$('#modalOK').modal('show');
		}

		function validacioCorreuButlleti() {
			var email = $('#adreca-electronica').val();
			var error = "";
			if (email.length != 0) {
				var tfld_email = $.trim(email);
				var emailFilter = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;
				var illegalChars = /[\(\)\<\>\,\;\:\\\"\[\]]/;
				if (!emailFilter.test(tfld_email)) {
					error = "El correu electr\u00F2nic no és v\u00E0lid";
				} else if (email.match(illegalChars)) {
					error = "El correu electr\u00F2nic té car\u0E0cters no permesos";
				}
			} else
				error = "Cal omplir el camp";
			return error;
		}

		$('.form-footer').on('click', '#news', function() {
			if (validacioCorreuButlleti() != '') {
				var missatgeError = "<p>Cal omplir el camp de l'adreça electrònica.</p>";
				mostrarErrorButlleti(missatgeError);
			} else {
				var correu = $('#adreca-electronica').val();
				var comprovaSpam = $("#butlletiSpam").val();

				var requestMailing = $.ajax({
					url: "https://www.prisma.cat/ajax/mailingNou.php",
					data: {
						correu: correu,
						comprova: comprovaSpam
					},
					method: "GET",
					dataType: "html"
				});

				requestMailing.done(function(message) {
					if (message == "ok") {
						var missatgeConsultaOK = "<p>T'has subscrit correctament al nostre butlletí electrònic.</p>";
						missatgeConsultaOK += "<p>En breu rebràs un missatge de confirmació en el correu ";
						missatgeConsultaOK += "<strong><span class='correu_consulta'>" + correu + "</span></strong>.</p>";
						missatgeConsultaOK += "<p>Si el missatge no arriba en 15 minuts, revisa la carpeta del correu brossa. ";
						missatgeConsultaOK += "<p>Gr&agrave;cies per confiar en PrisMa!</p>";
						mostrarSuccessButlleti(missatgeConsultaOK)
					} else {
						mostrarErrorButlleti(message)
					}
				});

				requestMailing.fail(function(jqXHRMailing, textStatusMailing, errorThrownMailing) {
					errorFunction(jqXHRMailing, textStatusMailing, errorThrownMailing, "Hi ha hagut un error en el request del Mailing: ");
				});
			}
		});

		function checkAcceptCookies() {
			if (localStorage.getItem("acceptCookies") == 'true') {
				$('#cntCookies').hide();
			}
		}
		checkAcceptCookies();
	});

	requestFooter.fail(function(jqXHR, textStatus, errorThrown) {
		errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request Footer: ");
	});
}

function acceptCookies() {
	localStorage.setItem("acceptCookies", "true");
	$('#cntCookies').slideUp();
	consentGrantedAdStorage();
	consentGrantedAdUserData();
	consentGrantedAdPersonalization();
	consentGrantedAnalyticsStorage();
}

mostrarHeaderFooter();

var urlPagina = window.location.pathname.split('?')[0];
if (urlPagina.substr(-1) == "/") urlPagina = urlPagina.substr(0, urlPagina.length - 1);
var dispositiu;
if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
	dispositiu = "mobil";
	$('#boto-tancar').css('display', 'none');
	$('#top-menu').remove()
} else {
	dispositiu = "ordinador"
}

let screenWidth = parseInt($(this).width());

let dataI = '';


/* ############################### FUNCIONALITATS ############################### */

/* Mostrem la pàgina que toca */
function mostrarUnaSolaTrobada() {
	var requestPage  = $.ajax({
		async: !0,
		url: "https://www.prisma.cat/ajax/mostrar_pagina_trobada.php",
		method: "GET",
		data: {
			url: urlPagina,
			dispositiu : dispositiu
		},
		dataType: "html"
	});

	/*
		Creem una classe CountdownTimer que utilitzarem per fer el countdown del video en directe.
		Cada vegada s'inicialitzarà la classe amb els paràmetres idElem, lastTime, msgLastTime on
		idElem correspon a l'id de l'element que contindrà el countdown,
		lastTime correspon a l'objecte Date creat amb la data límit,
		msgLastTime correspon al missatge que es mostrarà quan el temps s'hagi acabat
	*/
	function CountdownTimer( idElem, lastTime, msgLastTime ) {
		this.initialize.apply(this,arguments);
	}
	CountdownTimer.prototype = {
		initialize:function( idElem, lastTime, msgLastTime ) {
			this.idElem = document.getElementById(idElem);
			this.lastTime = lastTime;
			this.msgLastTime = msgLastTime;
		},
		countDown:function() {
			var msgHtml = '';
			var objMe = this;

			var today = new Date();
			var diff = this.lastTime - today;

			var day = Math.floor( diff / (24*60*60*1000) );
			var hour = Math.floor( (diff % (24*60*60*1000)) / (60*60*1000) );
			var min = Math.floor( (diff % (24*60*60*1000)) / (60*1000) ) % 60;
			var sec = Math.floor( (diff % (24*60*60*1000)) / 1000 ) % 60 % 60;

			if( diff > 0 ) {
				msgHtml += "<div class='col-12 col-sm-3 d-flex flex-column justify-content-center align-items-center px-4 my-3'>";
				msgHtml += "<span class='number'>" + day +"</span><span class='description mt-3'>Dies</span></div>";
				msgHtml += "<div class='col-12 col-sm-3 d-flex flex-column justify-content-center align-items-center px-4 my-3'>";
				msgHtml += "<span class='number'>" + hour +"</span><span class='description mt-3'>Hores</span></div>";
				msgHtml += "<div class='col-12 col-sm-3 d-flex flex-column justify-content-center align-items-center px-4 my-3'>";
				msgHtml += "<span class='number'>" + this.addZero(min) +"</span><span class='description mt-3'>Minuts</span></div>";
				msgHtml += "<div class='col-12 col-sm-3 d-flex flex-column justify-content-center align-items-center px-4 my-3'>";
				msgHtml += "<span class='number'>" + this.addZero(sec) +"</span><span class='description mt-3'>Segons</span></div>";

				this.idElem.innerHTML = msgHtml;

				tid = setTimeout( function() {
					objMe.countDown();
				}, 500 );
			}
			else {
				this.idElem.innerHTML = this.msgLastTime;
				location.reload(true);
				return;
			}
		},
		addZero:function( num ) {
			return ('0' + num).slice(-2);
		}
	}

	requestPage.done(function( page ) {
		$("#contingut").html(page);

		var reqDataI  = $.ajax({
			async: !0,
			url: "https://www.prisma.cat/ajax/mostrar_data_inici_trobada.php",
			method: "GET",
			dataType: "html"
		});

		reqDataI.done(function( msg ) {
			if ( !msg.toLowerCase().includes("error") && msg!='' ) {
				dataI = msg;

				// Creem la data limit del countDown
				var lastTime = new Date(dataI);
				var idCnt = "countdown-video-directe";
				var msgLastTime = "<div class='col-12 col-sm-3 d-flex flex-column justify-content-center align-items-center px-4 my-3'>";
				msgLastTime += "<span class='number'>Ja podeu visualitzar la trobada!</span></div>";

				if ( navigator.userAgent.toLowerCase().indexOf('safari') != -1
				&& navigator.userAgent.toLowerCase().indexOf('chrome') <= -1 ) {
					console.log('safari');
					$('#countdown-video-directe').html('');
				}
				else {
					// Creem un objecte CountdownTimer on indiquem la id on afegirem el countdown, la data limit i el missatge al acabar
					var timer = new CountdownTimer(idCnt, lastTime, msgLastTime);
					timer.countDown();
				}
			}
		});

		reqDataI.fail(function( jqXHR, textStatus, errorThrown ) {
			errorFunction( jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request de la pàgina: " );
		});

		/* Posar intermitent el botó de EN DIRECTE */
		$('.text-now .fa-circle').each(function() {
		    var elem = $(this);
		    setInterval(function() {
		        if (elem.css('visibility') == 'hidden') {
		            elem.css('visibility', 'visible');
		        } else {
		            elem.css('visibility', 'hidden');
		        }
		    }, 500);
		});

		/* Modal de subscripció */
		$('#modalSubscription').on('focus', '.form-control', function() {
			$(this).prev().addClass('active');
		});
		$('#modalSubscription').on('blur', '.form-control', function() {
			if ($(this).val().trim() == '')
				$(this).prev().removeClass('active');
		});

		$('#contingut').on('click', '#avis-trobada', function() {
			$('#modalSubscription').modal('show');
		});
		$('#modalSubscription').on('click', '#send-subscrition', function() {
			$('#modalSubscription .alert').remove();
			var errors = "";
			if ( !$("#mailing-all").is(':checked') ) {
				errors += "<span>Has de marcar l'opció «Avisa'm 30 minuts abans de la trobada</span>";
				$('#mailing-all').next().addClass("error");
			}
			else {
				$('#mailing-all').next().removeClass("error");
			}

			if ( $('#email-mailing').val().trim() == "" ) {
				errors += "<span>El camp del correu electrònic no pot estar buit</span>";
				$('#correu_erroni').addClass("erroni");
				$('#correu_erroni').html("Camp obligatori");
			}
			else {
				var email = $('#email-mailing').val().trim();
				var tfld_email = $.trim(email);
				var emailFilter = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;
				var illegalChars = /[\(\)\<\>\,\;\:\\\"\[\]]/;
				if (!emailFilter.test(tfld_email)) {
					errors += "<span>El correu electrònic no és vàlid</span>";
					$('#correu_erroni').addClass("erroni");
					$('#correu_erroni').html("Camp no vàlid");
				} else if (email.match(illegalChars)) {
					errors += "<span>El correu electrònic té caràcters no permesos</span>";
					$('#correu_erroni').addClass("erroni");
					$('#correu_erroni').html("Camp amb caràcters no permesos");
				}
				else {
					$('#correu_erroni').removeClass("erroni");
					$('#correu_erroni').html("");
				}
			}

			var msgError = "<div class='alert alert-danger alert-with-icon w-100 mb-2'>";
			msgError += "<i class='fas fa-bell' data-notify='icon'></i>";
			msgError += "<button type='button' data-dismiss='alert' aria-label='Close' class='close'>";
			msgError += "<i class='fas fa-time'></i></button>";
			msgError += errors + "</div>";

			if ( errors != "" )
				$('#modalSubscription .modal-body').append(msgError);
			else {
				var emailOK = $('#email-mailing').val().trim();
				var mailingCursos = $('#mailing-course').is(':checked');

				var htmlModal = "<p>T'has subscrit correctament al servei d'avís de la propera trobada en línia»";
				if ( mailingCursos ) {
					htmlModal += " i al nostre butlletí.</p>";
					htmlModal += "<p>En breu rebràs un missatge de confirmació en el correu ";
					htmlModal += "<strong><span class='correu_consulta'>" + emailOK + "</span></strong>.</p>";
					htmlModal += "<p>Si el missatge no arriba en 15 minuts, revisa la carpeta del correu brossa.</p>";
				}
				else {
					htmlModal += ".</p>";
				}
				htmlModal += "<p>Gràcies per confiar en PrisMa!</p>";

				$('#modalSubscription').modal('hide');
				$("#modalLoading").modal('show');
				//Consulta ajax

				var addMailing = $.ajax({
					async: !0,
					url: "https://www.prisma.cat/ajax/afegeix_usuari_mailing_trobada.php",
					method: "GET",
					data: {
						email : emailOK,
						dispositiu : dispositiu
					},
					dataType: "html"
				});

				addMailing.done(function(pagina) {
					if ( mailingCursos ) {
						var addMailingCourses = $.ajax({
							url: "https://www.prisma.cat/ajax/mailingNou.php",
							data: {
								correu: emailOK,
								comprova: ""
							},
							method: "GET",
							dataType: "html"
						});

						addMailingCourses.done(function(message) {
							$("#modalLoading").modal('hide');
							if (message == "ok") {
								$('#modalSubscriptionOK .modal-body').html(htmlModal);
							} else {
								$('#modalSubscriptionOK .modal-body').html(message);
							}
							$('#modalSubscriptionOK').modal('show');
						});

						addMailingCourses.fail(function(jqXHRMailing, textStatusMailing, errorThrownMailing) {
							errorFunction(jqXHRMailing, textStatusMailing, errorThrownMailing, "Hi ha hagut un error a l'hora de subscriure's al butlletí: ");
						});
					}
					else {
						$("#modalLoading").modal('hide');
						$('#modalSubscriptionOK .modal-body').html(htmlModal);
						$('#modalSubscriptionOK').modal('show');
					}

				});

				addMailing.fail(function(jqXHR, textStatus, errorThrown) {
					errorFunction(jqXHR, textStatus, errorThrown, "Hi ha hagut un error a l'hora de subscriure's: ");
				});

			}
		});
	});

	requestPage.fail(function( jqXHR, textStatus, errorThrown ) {
		errorFunction( jqXHR, textStatus, errorThrown, "Hi ha hagut un error en el request de la pàgina: " );
	});
}

mostrarUnaSolaTrobada();

function mostrarTaset(codi) {
	if (!$('#veure_tastet_'+codi)[0]) {
		var mostraTastet = $.ajax({
			url: "https://www.prisma.cat/ajax/mostrar_tastet.php",
			data: {
				dispositiu: dispositiu,
				codi: codi
			},
			method: "GET",
			dataType: "html"
		});

		mostraTastet.done(function(tastet) {
			$("#contingut_curs").append(tastet);

			//Mostrar el video de la presentacio del curs quan cliques la caratula
			var video  = $('#veure_tastet_'+codi+" .video-responsive");
			video.on("click", function(){
				var obj = $(this);
				$(this).find('iframe')[0].src=$(this).find('iframe')[0].src.replace("autoplay=0", "autoplay=1");
				setTimeout(function(){
					obj.find('button').hide();
					obj.find('img').hide();
				},500);
			});

			//Pausar el video quan surts del modal de veure un tastet
			$('#veure_tastet_'+codi).on('hide.bs.modal', function (e) {
				if ($(this).find('iframe')[0]) {
					var src= $(this).find('iframe')[0].src;
					$(this).find('iframe')[0].src = src;
					$(this).find('iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
					$(this).find('img').show();
					$(this).find('button').show();
				}
			});

			//Pausar el video de presentacioq quan s'obre un modal
			$('#veure_tastet_'+codi).on('show.bs.modal ', function (e) {
				if ($('#video-presentacio iframe')[0]) {
				  var src= $('#video-presentacio iframe')[0].src;
				  $('#video-presentacio iframe')[0].src = src;
				  $('#video-presentacio iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
				  $('#video-presentacio').find('img').show();
				  $('#video-presentacio').find('button').show();
			  }
			});
			$('#veure_tastet_'+codi).modal('show');
		});

		mostraTastet.fail(function(jqXHRMailing, textStatusMailing, errorThrownMailing) {
			errorFunction(jqXHRMailing, textStatusMailing, errorThrownMailing, "Hi ha hagut un error a l'hora de mostrar el tastet: ");
		});
	}
	else {
		$('#veure_tastet_'+codi).modal('show');
	}

}

/* ############################### GENERAL ############################### */
function adjustStyle() {
	screenWidth = parseInt($(this).width());

	if (screenWidth < 575) {
		$('.prisma-footer .panel').css('display', 'none');
		$('.accordion-footer').removeClass('active');
		$('.accordion-footer').click(function() {
			this.classList.toggle("active");
			var panel = this.nextElementSibling;
			if (panel.style.display === "block") {
				panel.style.display = "none";
				panel.style.maxHeight = null
			} else {
				panel.style.display = "block";
				panel.style.maxHeight = panel.scrollHeight + "px"
			}
		})
	}
	else {
		$('.accordion-footer').removeClass('active');
		$('.prisma-footer .panel').css('display', 'block')
	}
}

function afegirCSS() {
	$('body').append("<link rel='stylesheet' href='https://fonts.googleapis.com/css?family=Roboto:100,100i,300,400,400i,500,500i,700,700i|Nunito+Sans&display=swap' />");
	$('body').append("<link rel='stylesheet' href='https://www.prisma.cat/css1619773569/font-awesome-prisma.min.css?ver=1.0' />");
	$('body').append("<link rel='shortcut icon' type='image/x-icon' href='https://www.prisma.cat/favicon.ico'/>");
	$('body').append("<link rel='stylesheet' href='https://www.prisma.cat/css1619773569/404.min.css?ver=2.0' />")
}

afegirCSS();

function openNav() {
	$(".navbarPrisma").css('width', '270px');
	$('.closebtn').css('display', 'block');
	$('.navBarPrisma').addClass('w-100');
	$("#pagina").addClass('sideNavBarPrismaObert');
	$("#pagina > .container").addClass('sideNavBarContainerPrismaObert');
	$('body').css('overflow-y', 'hidden')
}

function closeNav() {
	$(".navbarPrisma").css('width', '0');
	$('.closebtn').css('display', 'none');
	$('.navBarPrisma').removeClass('w-100');
	$("#pagina").removeClass('sideNavBarPrismaObert');
	$("#pagina > .container").removeClass('sideNavBarContainerPrismaObert');
	$('body').css('overflow-y', 'auto')
}
window.onscroll = function() {
	noPerdreHeader()
};

function noPerdreHeader() {
	if (document.body.scrollTop > 0 || document.documentElement.scrollTop > 0) {
		$('#top-menu').css('display', 'none');
		$('#nav-header').css('position', 'fixed');
		$('#nav-header').css('top', '0')
	} else {
		if (!(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)))
			$('#top-menu').css('display', 'block');
		$('#nav-header').css('position', 'inherit')
	}
}
